const chapters={
 school:{title:"校园经历",kicker:"CHAPTER 01 / THE BEGINNING",subtitle:"青春有回声。那些晴天里的课桌，是故事开始的地方。",note:"这里将记录校园生活、学习轨迹，以及那些影响我的人和事。"},
 office:{title:"职场经历",kicker:"CHAPTER 02 / THE EVERYDAY",subtitle:"在现实中生长。在法律与日常之间，找到自己的位置。",note:"这里将记录法律相关工作、职业成长，以及日常工作的思考。"},
 cyber:{title:"赛博创造",kicker:"CHAPTER 03 / THE NEXT",subtitle:"把想象写成未来。与 AI 一起，把好奇心变成作品。",note:"这里将记录 AI 探索、Vibe Coding 实践，以及正在生长的个人项目。"}
};
const home=document.querySelector("#home"),detail=document.querySelector("#detail"),scenes=[...document.querySelectorAll(".scene")],reduced=matchMedia("(prefers-reduced-motion: reduce)"),hover=matchMedia("(hover:hover) and (pointer:fine)");
let active=null,busy=false,run=0,titleTimer=null;
function typeTitle(){clearTimeout(titleTimer);const node=document.querySelector("#typed-title"),intro=document.querySelector(".intro"),text=SiteI18n.t("我有无限可能");intro.classList.remove("is-typing");if(reduced.matches){node.textContent=text;return;}node.textContent="";intro.classList.add("is-typing");let n=0;function tick(){node.textContent=text.slice(0,++n);if(n<text.length)titleTimer=setTimeout(tick,160);else{titleTimer=setTimeout(()=>intro.classList.remove("is-typing"),450);}}titleTimer=setTimeout(tick,200);}
const preloads=new Map();
function preload(src){if(!preloads.has(src)){const img=new Image();img.src=src;preloads.set(src,img.decode().catch(()=>{}));}return preloads.get(src)}
Object.keys(chapters).forEach(key=>{preload("./assets/"+key+"-walk.gif");for(let i=1;i<=4;i++)preload("./assets/"+key+"-jump-"+i+".png");});
function clear(){scenes.forEach(el=>{el.classList.remove("is-active");const box=el.querySelector(".avatar");box.hidden=true;box.querySelector("img").removeAttribute("src");});active=null;}
function activate(key){if(busy||home.hidden)return;clear();const el=scenes.find(x=>x.dataset.key===key);if(!el)return;active=key;el.classList.add("is-active");const box=el.querySelector(".avatar");box.hidden=false;box.querySelector("img").src="./assets/"+key+(reduced.matches?"-still.png":"-walk.gif");}
function route(options={}){run++;busy=false;document.body.classList.remove("busy","routing");clear();const key=location.hash.slice(1);const data=chapters[key]&&Object.fromEntries(Object.entries(chapters[key]).map(([field,value])=>[field,SiteI18n.t(value)]));home.hidden=!!data;detail.hidden=!data;if(!data){document.title=SiteI18n.t("我有无限可能");typeTitle();return;}detail.classList.add("campus-detail");detail.dataset.chapter=key;document.querySelector("#campus-story").hidden=key!=="school";document.querySelector("#office-story").hidden=key!=="office";document.querySelector("#cyber-story").hidden=key!=="cyber";detail.querySelector(".chapter-placeholder").hidden=true;document.querySelector("#status").textContent="";document.title=data.title+" · "+SiteI18n.t("我有无限可能");detail.querySelector(".detail-art").style.backgroundImage='url("./assets/'+key+'.webp")';document.querySelector("#detail-kicker").textContent=data.kicker;document.querySelector("#detail-title").textContent=data.title;document.querySelector("#detail-subtitle").textContent=data.subtitle;document.querySelector("#detail-note").textContent=data.note;detail.querySelectorAll("nav a").forEach(a=>{if(a.hash==="#"+key)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current");});if(!options.preserveScroll){document.querySelector("#detail-title").focus({preventScroll:true});window.scrollTo(0,0);}}
const wait=ms=>new Promise(resolve=>setTimeout(resolve,ms));
async function enter(key,keyboard=false){if(busy)return;activate(key);busy=true;document.body.classList.add("busy");const token=++run;document.querySelector("#status").textContent=SiteI18n.t("正在进入")+SiteI18n.t(chapters[key].title);const el=scenes.find(x=>x.dataset.key===key),img=el.querySelector(".avatar img");try{if(!reduced.matches&&!keyboard){const times=[70,160,120,340];for(let i=1;i<=4;i++){const src="./assets/"+key+"-jump-"+i+".png";await preload(src);if(token!==run)return;img.src=src;await wait(times[i-1]);if(token!==run)return;}}if(token!==run)return;if(!reduced.matches&&!keyboard){document.body.classList.add("routing");await wait(200);}if(token!==run)return;location.hash=key;}catch{location.hash=key;}}
scenes.forEach(el=>{const key=el.dataset.key;el.addEventListener("pointerenter",e=>{if(e.pointerType!=="touch"&&hover.matches)activate(key)});el.addEventListener("pointerleave",()=>{if(!busy&&active===key)clear()});el.addEventListener("focus",()=>activate(key));el.addEventListener("blur",()=>{if(!busy)clear()});el.addEventListener("pointerdown",e=>{if(e.pointerType==="touch"){activate(key);}});el.addEventListener("click",e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();enter(key,e.detail===0)});});
window.addEventListener("hashchange",route);window.addEventListener("pageshow",()=>{if(!busy)route()});window.addEventListener("keydown",e=>{if(e.key==="Escape"){run++;busy=false;document.body.classList.remove("busy","routing");clear();document.querySelector("#status").textContent="";}});document.addEventListener("visibilitychange",()=>{if(document.hidden&&!busy)clear()});reduced.addEventListener("change",()=>{if(active&&!busy)activate(active);if(!home.hidden)typeTitle()});route();


document.querySelectorAll("[data-scroll]").forEach(button=>button.addEventListener("click",()=>{const target=document.getElementById(button.dataset.scroll);target.scrollIntoView({behavior:reduced.matches?"instant":"smooth",block:"start"});target.focus({preventScroll:true});}));

// Keep the current chapter, reading position and keyboard focus when switching languages.
document.querySelectorAll('[data-language]').forEach(button=>button.addEventListener('click',()=>{
 if(button.dataset.language===SiteI18n.language)return;
 SiteI18n.setLanguage(button.dataset.language);
 const address=new URL(location.href);address.searchParams.set('lang',SiteI18n.language);history.replaceState(null,'',address);
 route({preserveScroll:true});
}));
